-- Konsens V3 action RPCs.
create or replace function public.create_league(p_name text,p_dimension text default 'score') returns uuid language plpgsql security definer set search_path=public as $$declare lid uuid;code text;begin code:=upper(substr(encode(gen_random_bytes(6),'hex'),1,6));insert into public.leagues(name,join_code,owner_id,ranking_dimension,description,is_public) values(left(trim(p_name),60),code,auth.uid(),coalesce(nullif(p_dimension,''),'score'),'Ligue Konsens',false) returning id into lid;insert into public.league_members(league_id,user_id) values(lid,auth.uid()) on conflict do nothing;return lid;end$$;grant execute on function public.create_league(text,text) to authenticated;
create or replace function public.join_league(p_code text) returns uuid language plpgsql security definer set search_path=public as $$declare lid uuid;begin select id into lid from public.leagues where upper(join_code)=upper(trim(p_code)) limit 1;if lid is null then raise exception 'league_not_found';end if;insert into public.league_members(league_id,user_id) values(lid,auth.uid()) on conflict do nothing;return lid;end$$;grant execute on function public.join_league(text) to authenticated;
create or replace function public.get_my_leagues() returns table(id uuid,name text,join_code text,ranking_dimension text,member_count bigint) language sql stable security definer set search_path=public as $$select l.id,l.name,l.join_code,l.ranking_dimension,count(allm.user_id) from public.leagues l join public.league_members me on me.league_id=l.id and me.user_id=auth.uid() left join public.league_members allm on allm.league_id=l.id group by l.id,l.name,l.join_code,l.ranking_dimension order by l.created_at desc$$;grant execute on function public.get_my_leagues() to authenticated;
create or replace function public.get_league_rankings(p_league_id uuid) returns table(user_id uuid,username text,total_score numeric,prediction_score numeric,knowledge_score numeric,risk_score numeric,rank bigint) language sql stable security definer set search_path=public as $$select lm.user_id,p.username,coalesce(k.total_score,50),coalesce(k.prediction_score,50),coalesce(k.knowledge_score,50),coalesce(k.risk_score,50),rank() over(order by coalesce(k.total_score,50) desc) from public.league_members lm join public.profiles p on p.id=lm.user_id left join public.konsens_scores k on k.user_id=lm.user_id where lm.league_id=p_league_id and exists(select 1 from public.league_members me where me.league_id=p_league_id and me.user_id=auth.uid())$$;grant execute on function public.get_league_rankings(uuid) to authenticated;
create or replace function public.save_decision_note(p_trade_order_id uuid,p_reason text,p_confidence smallint,p_thesis text,p_expectation text default null,p_emotion text default null) returns uuid language plpgsql security definer set search_path=public as $$declare oid uuid;tid uuid;aid uuid;mid uuid;credits numeric;price numeric;dtype text;outcome text;begin select id,asset_id,market_id,trade_orders.credits,execution_price,case when market_id is not null then 'bet' else 'investment' end,trade_orders.outcome into tid,aid,mid,credits,price,dtype,outcome from public.trade_orders where id=p_trade_order_id and user_id=auth.uid() and status='executed';if tid is null then raise exception 'trade_not_found';end if;insert into public.decision_journal(user_id,trade_order_id,decision_type,asset_id,market_id,outcome,reason_code,confidence,thesis,credits,entry_price,expectation,emotion) values(auth.uid(),tid,dtype,aid,mid,outcome,left(coalesce(p_reason,'other'),30),greatest(0,least(100,p_confidence)),left(coalesce(p_thesis,''),500),credits,price,left(coalesce(p_expectation,''),300),left(coalesce(p_emotion,''),50)) on conflict(trade_order_id) do update set reason_code=excluded.reason_code,confidence=excluded.confidence,thesis=excluded.thesis,expectation=excluded.expectation,emotion=excluded.emotion returning id into oid;return oid;end$$;grant execute on function public.save_decision_note(uuid,text,smallint,text,text,text) to authenticated;
create or replace function public.get_profile_card() returns table(username text,total_score numeric,archetype text,prediction_score numeric,risk_score numeric,knowledge_score numeric,discipline_score numeric,streak_days integer,total_wealth numeric) language sql stable security definer set search_path=public as $$select p.username,coalesce(k.total_score,50),coalesce(k.archetype,'Explorateur'),coalesce(k.prediction_score,50),coalesce(k.risk_score,50),coalesce(k.knowledge_score,50),coalesce(k.discipline_score,50),coalesce(k.streak_days,0),coalesce(w.total_value,1000) from public.profiles p left join public.konsens_scores k on k.user_id=p.id left join lateral public.get_my_wealth_snapshot() w on true where p.id=auth.uid()$$;grant execute on function public.get_profile_card() to authenticated;
